function displayValue(n){return n==null||n===""?"—":n}function addSection(n,t){let i='<article class="prom-info-card"><h3>'+n+"<\/h3><table><tbody>";for(let n=0;n<t.length;n++)i+="<tr><th>"+t[n][0]+"<\/th><td>"+displayValue(t[n][1])+"<\/td><\/tr>";return i+="<\/tbody><\/table><\/article>"}async function loadSystemInfo(){const n=document.getElementById("content");try{const r=await Promethe.api("systeminfo.json");if(!r.ok)throw new Error("request failed");const t=await r.json();let i="";i+=addSection("Console",[["CPU",t.console.cpuMhz+" MHz"],["GPU",t.console.gpuMhz+" MHz"],["FSB",t.console.fsbMhz+" MHz"],["RAM Clock",t.console.memMhz+" MHz"],["RAM Size",t.console.ramMb+" MB"],["Xbox Revision",t.console.xboxRev],["Serial",t.console.serial],["MAC",t.console.mac]]);const u=[["Primary Drive",t.storage.primaryModel],["Primary Serial",t.storage.primarySerial],["Secondary Drive",t.storage.secondaryModel],["Secondary Serial",t.storage.secondarySerial]];if(i+=addSection("Storage",u),t.storage.partitions&&t.storage.partitions.length>0){let n='<article class="prom-info-card"><h3>Partitions<\/h3><table><tbody>';for(let i=0;i<t.storage.partitions.length;i++){const r=t.storage.partitions[i],u=r.total>0?Math.round(r.used/r.total*100):0;n+="<tr><th>"+r.label+"<\/th><td>"+Promethe.formatBytes(r.used)+" / "+Promethe.formatBytes(r.total)+" ("+u+"%)<\/td><\/tr>"}n+="<\/tbody><\/table><\/article>";i+=n}i+=addSection("Audio",[["Mode",t.audio.mode],["AC3",t.audio.ac3?"Yes":"No"],["DTS",t.audio.dts?"Yes":"No"]]);i+=addSection("Video",[["Standard",t.video.standard],["Game Region",t.video.gameRegion],["DVD Region",t.video.dvdRegion],["AV Pack",t.video.avPack],["Resolution",t.video.avRes],["Encoder",t.video.encoder]]);i+=addSection("About",[["PrometheOS",t.about.version],["Build",t.about.build],["Skin Author",t.about.skinAuthor],["IP Address",t.about.ip]]);n.innerHTML=i}catch(t){n.textContent="Failed to connect."}}window.onload=function(){document.getElementById("year").textContent=(new Date).getFullYear();loadSystemInfo()};